            for ri,c in enumerate(cols):
                val=getattr(row,c);x=gi+(j-(len(b)-1)/2)*.065+(ri-(len(cols)-1)/2)*.018;ax.scatter(x,val,s=10,color=BLUE if gi==0 else ORANGE,facecolors=('none' if not row.eligible else BLUE if gi==0 else ORANGE),alpha=.75)
